  <link rel="stylesheet" href="styles.css" />
</head>
<body>
  <div class="site-shell">
    <header class="site-header" aria-label="Primary navigation">
      <a class="logo" href="index.html" aria-label="StreamWave home">StreamWave</a>
      <nav class="header-actions" aria-label="Header actions">
        <label class="sr-only" for="language-home">Select language</label>
        <select id="language-home" class="language-select" aria-label="Select language">
          <option>English</option>
          <option>Español</option>
          <option>Français</option>
        </select>
        <a class="signin-button" href="login.html">Sign In</a>
      </nav>
    </header>

    <main>
      <section class="hero section-divider" aria-labelledby="hero-title">
        <div class="poster-mosaic" aria-hidden="true">
          <span class="poster poster-1">ACTION</span>
          <span class="poster poster-2">DRAMA</span>
          <span class="poster poster-3">ANIME</span>
          <span class="poster poster-4">SCI-FI</span>
          <span class="poster poster-5">DOCS</span>
          <span class="poster poster-6">KIDS</span>
          <span class="poster poster-7">ROMANCE</span>
          <span class="poster poster-8">THRILLER</span>
        </div>
        <div class="hero-glow" aria-hidden="true"></div>
        <div class="hero-content">
          <p class="eyebrow">Unlimited entertainment. One membership.</p>
          <h1 id="hero-title">Unlimited films, series and more</h1>
          <p class="hero-subtitle">Starts at $15.98. Cancel at any time.</p>
          <form class="email-form" action="#" aria-label="Start StreamWave membership">
            <p>Ready to watch? Enter your email to create or restart your membership.</p>
            <div class="email-row">
              <label class="sr-only" for="hero-email">Email address</label>
              <input id="hero-email" type="email" name="email" placeholder="Email address" autocomplete="email" required />
              <button class="primary-cta" type="submit">Get Started <span aria-hidden="true">›</span></button>
            </div>
          </form>
        </div>
      </section>

      <section class="content-section trending-section" aria-labelledby="trending-title">
        <div class="section-heading-row">
          <h2 id="trending-title">Trending now</h2>
          <div class="carousel-controls" aria-label="Trending carousel controls">
            <button class="carousel-button" type="button" data-carousel-prev aria-label="Scroll trending titles left">‹</button>
            <button class="carousel-button" type="button" data-carousel-next aria-label="Scroll trending titles right">›</button>
          </div>
        </div>
        <div class="carousel-viewport">
          <ol class="trending-carousel" data-carousel aria-label="Top 10 trending titles">
            <li class="title-card card-red"><span class="rank">1</span><span class="genre">Crime Series</span><strong>Bloodhounds</strong></li>
            <li class="title-card card-gold"><span class="rank">2</span><span class="genre">Limited Series</span><strong>BEEF</strong></li>
            <li class="title-card card-pink"><span class="rank">3</span><span class="genre">Teen Drama</span><strong>XO, Kitty</strong></li>
            <li class="title-card card-blue"><span class="rank">4</span><span class="genre">War Thriller</span><strong>War Machine</strong></li>
            <li class="title-card card-violet"><span class="rank">5</span><span class="genre">Period Drama</span><strong>Bridgerton</strong></li>
            <li class="title-card card-indigo"><span class="rank">6</span><span class="genre">Sci-Fi Horror</span><strong>Stranger Things</strong></li>
            <li class="title-card card-cyan"><span class="rank">7</span><span class="genre">Fantasy</span><strong>Agent from Above</strong></li>
            <li class="title-card card-orange"><span class="rank">8</span><span class="genre">Romance</span><strong>Boyfriend on Demand</strong></li>
            <li class="title-card card-neon"><span class="rank">9</span><span class="genre">Animated Event</span><strong>KPop Demon Hunters</strong></li>
            <li class="title-card card-paris"><span class="rank">10</span><span class="genre">Comedy Drama</span><strong>Emily in Paris</strong></li>
          </ol>
        </div>
      </section>

      <section class="content-section" aria-labelledby="features-title">
        <h2 id="features-title">More reasons to join</h2>
        <div class="feature-grid">
          <article class="feature-card">
            <h3>Enjoy on your TV</h3>
            <p>Watch on smart TVs, PlayStation, Xbox, Chromecast, Apple TV, Blu-ray players and more.</p>
            <span class="feature-icon" aria-hidden="true">▣</span>
          </article>
          <article class="feature-card">
            <h3>Download your series to watch offline</h3>
            <p>Save your favourites easily and always have something to watch.</p>
            <span class="feature-icon" aria-hidden="true">⇣</span>
          </article>
          <article class="feature-card">
            <h3>Watch everywhere</h3>
            <p>Stream unlimited films and series on your phone, tablet, laptop and TV.</p>
            <span class="feature-icon" aria-hidden="true">◌</span>
          </article>
          <article class="feature-card">
            <h3>Create profiles for children</h3>
            <p>Send children on adventures with their favourite characters in a space made just for them — free with your membership.</p>
            <span class="feature-icon" aria-hidden="true">★</span>
          </article>
        </div>
      </section>

      <section class="content-section faq-section" aria-labelledby="faq-title">
        <h2 id="faq-title">Frequently Asked Questions</h2>
        <div class="faq-list" data-accordion>
          <article class="faq-item is-open">
            <button class="faq-question" type="button" aria-expanded="true">What is StreamWave?<span aria-hidden="true">+</span></button>
            <div class="faq-answer">
              <p>StreamWave is a streaming service that offers a wide variety of award-winning TV programmes, films, anime, documentaries and more — on thousands of internet-connected devices. You can watch as much as you want, whenever you want, without a single advert — all for one low monthly price. There's always something new to discover, and new TV programmes and films are added every week!</p>
            </div>
          </article>
          <article class="faq-item">
            <button class="faq-question" type="button" aria-expanded="false">How much does StreamWave cost?<span aria-hidden="true">+</span></button>
            <div class="faq-answer">
              <p>Watch StreamWave on your smartphone, tablet, smart TV, laptop or streaming device, all for one fixed monthly fee. Plans range from $15.98 to $29.98/month.</p>
            </div>
          </article>
          <article class="faq-item">
            <button class="faq-question" type="button" aria-expanded="false">Where can I watch?<span aria-hidden="true">+</span></button>
            <div class="faq-answer">
              <p>Watch anywhere, anytime. Sign in with your StreamWave account to watch instantly on the web from your personal computer or on any internet-connected device that offers the StreamWave app, including smart TVs, smartphones, tablets, streaming media players and game consoles. You can also download your favourite programmes with the iOS or Android app. Use downloads to watch while you're on the go and without an internet connection. Take StreamWave with you anywhere.</p>
            </div>
          </article>
          <article class="faq-item">
            <button class="faq-question" type="button" aria-expanded="false">How do I cancel?<span aria-hidden="true">+</span></button>
            <div class="faq-answer">
              <p>StreamWave is flexible. You can easily cancel your account online in two clicks. There are no cancellation fees — start or stop your account at any time.</p>
            </div>
          </article>
          <article class="faq-item">
            <button class="faq-question" type="button" aria-expanded="false">What can I watch on StreamWave?<span aria-hidden="true">+</span></button>
            <div class="faq-answer">
              <p>StreamWave has an extensive library of feature films, documentaries, series, anime, award-winning StreamWave originals, and more. Watch as much as you want, any time you want.</p>
            </div>
          </article>
          <article class="faq-item">
            <button class="faq-question" type="button" aria-expanded="false">Is StreamWave good for children?<span aria-hidden="true">+</span></button>
            <div class="faq-answer">
              <p>The StreamWave Children's experience is included in your membership to give parents control while children enjoy family-friendly TV programmes and films in their own space. Children's profiles come with PIN-protected parental controls that let you restrict the maturity rating of content children can watch and block specific titles you don't want children to see.</p>
            </div>
          </article>
        </div>
      </section>

      <section class="bottom-cta" aria-label="Start watching StreamWave">
        <div>
          <p class="eyebrow">Start in minutes</p>
          <h2>Ready to press play?</h2>
        </div>
        <form class="email-form compact" action="#" aria-label="Create or restart StreamWave membership">
          <p>Ready to watch? Enter your email to create or restart your membership.</p>
          <div class="email-row">
            <label class="sr-only" for="cta-email">Email address</label>
            <input id="cta-email" type="email" name="email" placeholder="Email address" autocomplete="email" required />
            <button class="primary-cta" type="submit">Get Started <span aria-hidden="true">›</span></button>
          </div>
        </form>
      </section>
    </main>

    <footer class="site-footer">
      <p>Questions? Contact us.</p>
      <div class="footer-grid" aria-label="Footer links">
        <a href="#faq-title">FAQ</a>
        <a href="#">Help Centre</a>
        <a href="#">Account</a>
        <a href="#">Media Centre</a>
        <a href="#">Investor Relations</a>
        <a href="#">Jobs</a>
        <a href="#">Ways to Watch</a>
        <a href="#">Terms of Use</a>
        <a href="#">Privacy</a>
        <a href="#">Cookie Preferences</a>
        <a href="#">Corporate Information</a>
        <a href="#">Contact Us</a>
        <a href="#">Speed Test</a>
        <a href="#">Legal Notices</a>
        <a href="#">Only on StreamWave</a>
      </div>
      <label class="sr-only" for="footer-language-home">Select language</label>
      <select id="footer-language-home" class="language-select footer-language" aria-label="Select language">
        <option>English</option>
        <option>Español</option>
        <option>Français</option>
      </select>
      <p class="legal-note">This page is protected by Google reCAPTCHA to ensure you're not a bot.</p>
    </footer>
  </div>
  <script src="script.js"></script>
</body>
</html>
