cat > /app/output/styles.css <<'EOF'
:root {
  --bg: #000000;
  --bg-soft: #141414;
  --panel: #1d1d22;
  --panel-2: #26262d;
  --text: #ffffff;
  --muted: #b8b8c2;
  --red: #e50914;
  --red-hover: #f51b25;
  --line: rgba(255, 255, 255, 0.14);
  --shadow: 0 28px 80px rgba(0, 0, 0, 0.55);
  --max: 1180px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}
body::selection { background: var(--red); color: white; }
a { color: inherit; }
button, input, select { font: inherit; }
.site-shell { min-height: 100vh; overflow: hidden; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.site-header {
  position: absolute;
  top: 0;
  left: 50%;
  z-index: 20;
  width: min(100% - 32px, var(--max));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 24px 0;
}
.logo {
  text-decoration: none;
  color: var(--red);
  font-family: "Bebas Neue", Impact, sans-serif;
  font-size: clamp(2.1rem, 5vw, 3.3rem);
  letter-spacing: 0.04em;
  text-shadow: 0 0 24px rgba(229, 9, 20, 0.35);
  line-height: 0.9;
}
.header-actions { display: flex; align-items: center; gap: 12px; }
.language-select {
  min-height: 34px;
  border: 1px solid rgba(255,255,255,0.45);
  border-radius: 6px;
  background: rgba(10,10,10,0.72);
  color: white;
  padding: 6px 34px 6px 12px;
  backdrop-filter: blur(8px);
}
.signin-button,
.primary-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  background: var(--red);
  color: white;
  text-decoration: none;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 14px 32px rgba(229, 9, 20, 0.32);
  transition: transform 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}
.signin-button { min-height: 34px; padding: 7px 16px; font-size: 0.9rem; }
.primary-cta { min-height: 58px; padding: 14px 27px; font-size: clamp(1.06rem, 2.1vw, 1.45rem); gap: 8px; white-space: nowrap; }
.signin-button:hover,
.primary-cta:hover { background: var(--red-hover); transform: translateY(-1px); box-shadow: 0 18px 38px rgba(229, 9, 20, 0.42); }

.hero {
  position: relative;
  min-height: 760px;
  display: grid;
  place-items: center;
  padding: 132px 16px 88px;
  isolation: isolate;
  background:
    radial-gradient(circle at 50% 78%, rgba(229,9,20,0.22), transparent 34%),
    linear-gradient(180deg, rgba(0,0,0,0.45) 0%, #000 96%);
}
.hero::before,
.hero::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: -1;
}
.hero::before {
  background: linear-gradient(90deg, #000 0%, transparent 18%, transparent 82%, #000 100%),
              linear-gradient(180deg, rgba(0,0,0,0.62), rgba(0,0,0,0.28) 42%, #000 100%);
}
.hero::after {
  inset: auto 0 0;
  height: 6px;
  background: linear-gradient(90deg, transparent, var(--red), #7426ff, transparent);
  opacity: 0.85;
}
.poster-mosaic {
  position: absolute;
  inset: 0;
  z-index: -2;
  overflow: hidden;
  opacity: 0.72;
  filter: saturate(1.25) contrast(1.08);
}
.poster {
  position: absolute;
  display: grid;
  place-items: end start;
  width: 178px;
  height: 260px;
  padding: 18px;
  border-radius: 12px;
  color: rgba(255,255,255,0.88);
  font-family: "Bebas Neue", Impact, sans-serif;
  font-size: 2rem;
  letter-spacing: 0.05em;
  box-shadow: var(--shadow), inset 0 0 0 1px rgba(255,255,255,0.08);
  background: linear-gradient(145deg, rgba(229,9,20,0.95), rgba(18,18,22,0.9));
  transform: rotate(var(--tilt));
}
.poster::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.24), transparent 28%), linear-gradient(0deg, rgba(0,0,0,0.76), transparent 56%);
}
.poster { --tilt: -7deg; }
.poster-1 { top: 115px; left: 3%; background: linear-gradient(140deg, #d20b15, #231015); }
.poster-2 { top: 86px; left: 18%; --tilt: 5deg; background: linear-gradient(140deg, #b87822, #140f0c); }
.poster-3 { top: 132px; right: 20%; --tilt: -4deg; background: linear-gradient(140deg, #db2f86, #1d1024); }
.poster-4 { top: 96px; right: 4%; --tilt: 7deg; background: linear-gradient(140deg, #243fd1, #080b25); }
.poster-5 { bottom: 105px; left: 9%; --tilt: 8deg; background: linear-gradient(140deg, #168d87, #071716); }
.poster-6 { bottom: 62px; left: 31%; --tilt: -5deg; background: linear-gradient(140deg, #852bda, #170a21); }
.poster-7 { bottom: 92px; right: 31%; --tilt: 6deg; background: linear-gradient(140deg, #e33b45, #2a0913); }
.poster-8 { bottom: 112px; right: 10%; --tilt: -8deg; background: linear-gradient(140deg, #f06513, #241006); }
.hero-glow {
  position: absolute;
  width: min(780px, 86vw);
  height: 340px;
  border-radius: 999px;
  background: rgba(0,0,0,0.72);
  box-shadow: 0 0 120px 140px rgba(0,0,0,0.62);
  z-index: -1;
}
.hero-content {
  max-width: 950px;
  margin: 0 auto;
  text-align: center;
}
.eyebrow {
  margin: 0 0 12px;
  color: #ffb9bd;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.82rem;
}
h1, h2, h3, p { margin-top: 0; }
h1 {
  margin-bottom: 14px;
  font-size: clamp(3rem, 8.4vw, 6.9rem);
  line-height: 0.88;
  letter-spacing: -0.075em;
  font-weight: 900;
}
.hero-subtitle {
  margin-bottom: 28px;
  font-size: clamp(1.15rem, 2.4vw, 1.65rem);
  font-weight: 700;
}
.email-form p {
  margin-bottom: 15px;
  color: rgba(255,255,255,0.92);
  font-size: clamp(1rem, 1.7vw, 1.16rem);
  font-weight: 500;
}
.email-row {
  display: flex;
  justify-content: center;
  gap: 10px;
}
.email-row input {
  width: min(440px, 100%);
  min-height: 58px;
  border: 1px solid rgba(255,255,255,0.42);
  border-radius: 6px;
  background: rgba(16,16,18,0.78);
  color: white;
  padding: 16px 18px;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}
.email-row input:focus,
.login-form input:focus { border-color: white; box-shadow: 0 0 0 3px rgba(229, 9, 20, 0.35); }

.content-section {
  width: min(100% - 32px, var(--max));
  margin: 0 auto;
  padding: clamp(46px, 7vw, 78px) 0 0;
}
h2 {
  margin-bottom: 22px;
  font-size: clamp(1.75rem, 3.4vw, 2.75rem);
  line-height: 1.05;
  letter-spacing: -0.045em;
  font-weight: 900;
}
.section-heading-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.carousel-controls { display: flex; gap: 10px; }
.carousel-button {
  width: 44px;
  height: 58px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255,255,255,0.1);
  color: white;
  font-size: 2rem;
  cursor: pointer;
  transition: background 0.18s ease, transform 0.18s ease;
}
.carousel-button:hover { background: rgba(229,9,20,0.9); transform: translateY(-1px); }
.carousel-viewport { position: relative; }
.trending-carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: clamp(152px, 19vw, 218px);
  gap: clamp(14px, 2vw, 25px);
  margin: 0;
  padding: 14px 4px 20px 28px;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scroll-snap-type: inline mandatory;
  scrollbar-width: thin;
  scrollbar-color: var(--red) transparent;
}
.title-card {
  position: relative;
  scroll-snap-align: start;
  min-height: clamp(220px, 29vw, 310px);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: visible;
  list-style: none;
  padding: 18px;
  border-radius: 14px;
  isolation: isolate;
  background: linear-gradient(150deg, #2b2b31, #0c0c10);
